import{_ as a,C as o,o as r,c as n,E as i,a2 as s}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse('{"title":"行业架构观察周报 002 — 企业软件正从记录系统走向执行系统","description":"","frontmatter":{"title":"行业架构观察周报 002 — 企业软件正从记录系统走向执行系统","date":"2026-08-02","column":"industry-architecture","category":"weekly","summary":"Oracle、Salesforce 与 ServiceNow 正把 Agent 嵌入业务对象、工作流、权限、审批与审计，使企业软件从被动记录工作转向主动执行受治理结果。","sources":["Oracle Fusion Agentic Applications and AI Agent Studio","Salesforce Agentforce","ServiceNow Autonomous Workforce"],"outline":"deep","cover":"/assets/covers/systems-of-record-to-execution-cover-v2.jpg"},"headers":[],"relativePath":"zh/industry/2026-08-02-from-systems-of-record-to-systems-of-execution.md","filePath":"zh/industry/2026-08-02-from-systems-of-record-to-systems-of-execution.md","lastUpdated":1787407830000}'),l={name:"zh/industry/2026-08-02-from-systems-of-record-to-systems-of-execution.md"};function c(d,e,p,h,g,u){const t=o("ArticleCover");return r(),n("div",null,[i(t,{image:"/assets/covers/systems-of-record-to-execution-cover-v2.jpg",kicker:"行业架构 · 观察周报 002",title:"企业软件正从记录系统走向执行系统",summary:"Oracle、Salesforce 与 ServiceNow 正把 Agent 嵌入业务对象、工作流、权限、审批与审计。",version:"IW002",status:"发布于 2026-08-02",languageHref:"/en/industry/2026-08-02-from-systems-of-record-to-systems-of-execution",languageLabel:"English"}),e[0]||(e[0]=s(`<h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>传统企业软件的核心职责是记录：客户、员工、财务、资产、流程状态和交易历史。Agentic Enterprise Software 正在增加第二种职责：在相同的数据、权限和工作流环境中主动执行工作。</p><p>Oracle 将 Fusion Agentic Applications 定义为由专门 Agent 团队支撑、能够使用 Fusion 业务对象、工作流、政策、审批和日志动作完成结果的应用；Salesforce Agentforce 将数据、业务逻辑、Skill、Workflow 与 Agent 执行整合为数字劳动力平台；ServiceNow Autonomous Workforce 则以有岗位、有权限和治理边界的 AI Specialist 执行端到端企业流程。</p><p>本报告的判断是：</p><blockquote><p>企业软件不会被一个脱离业务系统的通用 Agent 层简单替代。更可能的方向，是 System of Record 与受治理的 System of Execution 在同一事务环境中结合。</p></blockquote><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>本周入选三类官方材料：</p><ol><li><strong>Oracle Fusion Agentic Applications / AI Agent Studio</strong>：重点是 Agent 团队原生运行在 Fusion Applications 内部，继承业务对象、权限、工作流、审批与审计。</li><li><strong>Salesforce Agentforce</strong>：重点是 Agent 使用 Data 360、CRM Metadata、Skill、Flow 和业务逻辑采取行动。</li><li><strong>ServiceNow Autonomous Workforce</strong>：重点是 AI Specialist 以明确岗位、权限、政策、Trace 和人工升级完成端到端工作。</li></ol><p>厂商对“第一”“无限劳动力”“全面自主”等市场语言不作为研究结论。本报告只分析其公开架构机制。</p><h2 id="weekly-highlights" tabindex="-1">Weekly Highlights <a class="header-anchor" href="#weekly-highlights" aria-label="Permalink to &quot;Weekly Highlights&quot;">​</a></h2><h3 id="_1-agent-正在进入交易系统内部" tabindex="-1">1. Agent 正在进入交易系统内部 <a class="header-anchor" href="#_1-agent-正在进入交易系统内部" aria-label="Permalink to &quot;1. Agent 正在进入交易系统内部&quot;">​</a></h3><p>Oracle 明确反对把 Agent 作为企业系统外部的附加层。Fusion Agentic Applications 直接针对 Fusion 业务对象、工作流、工具、政策和审批执行，并继承现有安全与审计。</p><p>Salesforce 也把 Agentforce 建立在企业数据、Metadata、Flow 和既有应用逻辑之上。ServiceNow 则把 AI Specialist 接入其工作流与企业记录系统。</p><p>行业正在从“Agent 调用几个 API”走向“Agent 成为业务系统内受治理的执行主体”。</p><h3 id="_2-产品单位从-agent-变成-agentic-application-或-workforce" tabindex="-1">2. 产品单位从 Agent 变成 Agentic Application 或 Workforce <a class="header-anchor" href="#_2-产品单位从-agent-变成-agentic-application-或-workforce" aria-label="Permalink to &quot;2. 产品单位从 Agent 变成 Agentic Application 或 Workforce&quot;">​</a></h3><p>Oracle 最新表达不是单个 Agent，而是由专门 Agent 团队、用户体验、Workflow、Tool、Policy、Approval 与 Runtime Asset 共同构成的 Agentic Application。</p><p>ServiceNow 使用 Autonomous Workforce 与 AI Specialist；Salesforce 使用 Digital Labor Platform。共同变化是：市场开始销售可完成业务结果的系统，而不是一个抽象 Agent Framework。</p><h3 id="_3-确定性流程与概率智能开始组合" tabindex="-1">3. 确定性流程与概率智能开始组合 <a class="header-anchor" href="#_3-确定性流程与概率智能开始组合" aria-label="Permalink to &quot;3. 确定性流程与概率智能开始组合&quot;">​</a></h3><p>三个体系都没有把全部执行权交给模型：</p><ul><li>Oracle 保留业务对象、角色权限、审批和可审计动作；</li><li>Salesforce 强调 Hybrid Reasoning、Flow、业务逻辑与安全；</li><li>ServiceNow 将 AI Specialist 放入确定性 Workflow、政策和人工升级。</li></ul><p>概率智能负责理解与判断，确定性系统负责权限、状态、交易和完成边界。</p><h2 id="cross-analysis" tabindex="-1">Cross Analysis <a class="header-anchor" href="#cross-analysis" aria-label="Permalink to &quot;Cross Analysis&quot;">​</a></h2><h3 id="三类企业执行平台对照" tabindex="-1">三类企业执行平台对照 <a class="header-anchor" href="#三类企业执行平台对照" aria-label="Permalink to &quot;三类企业执行平台对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>架构维度</th><th>Oracle Fusion Agentic Applications</th><th>Salesforce Agentforce</th><th>ServiceNow Autonomous Workforce</th></tr></thead><tbody><tr><td>主要定位</td><td>Fusion 内原生 Agentic Application</td><td>企业数字劳动力平台</td><td>企业 AI Specialist 劳动力</td></tr><tr><td>核心数据上下文</td><td>Fusion 业务对象、知识、API</td><td>Data 360、CRM 数据与 Metadata</td><td>ServiceNow 数据、CMDB、企业连接</td></tr><tr><td>工作执行</td><td>Agent 团队 + Workflow + Tool</td><td>Reasoning + Skill + Flow + Action</td><td>Specialist + 确定性 Workflow</td></tr><tr><td>权限基础</td><td>Fusion Role-Based Access</td><td>Salesforce Trust、权限与业务逻辑</td><td>Scope、Authority、Policy、Escalation</td></tr><tr><td>人工介入</td><td>审批与业务流程节点</td><td>Flow 与业务规则中的人工步骤</td><td>明确人工升级条件</td></tr><tr><td>审计与观察</td><td>Logged Actions、Validation、Auditability</td><td>Observability、Security、业务记录</td><td>Trace、Control Tower、Workflow History</td></tr><tr><td>第三方连接</td><td>Connector、API、第三方 Agent</td><td>外部系统、MuleSoft 与开放连接</td><td>跨云、模型和系统编排</td></tr><tr><td>主要优势</td><td>事务系统原生执行</td><td>CRM、数据和自动化整合</td><td>Workflow、IT 治理和运行控制</td></tr></tbody></table><p><strong>说明：</strong> 此表为官方公开架构能力的定性整理，不是性能或市场份额评测。</p><h3 id="从记录到执行的架构变化" tabindex="-1">从记录到执行的架构变化 <a class="header-anchor" href="#从记录到执行的架构变化" aria-label="Permalink to &quot;从记录到执行的架构变化&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统 System of Record</span></span>
<span class="line"><span>  数据 + 业务对象 + 权限 + 交易历史</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>            Agentic Execution Layer</span></span>
<span class="line"><span>  Reasoning + Skill + Tool + Workflow + Agent Team</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>         Governed Business Outcome</span></span>
<span class="line"><span>  Approval + Transaction + Evidence + Audit + Recovery</span></span></code></pre></div><p><em>图示：joinwell52 Research Center 综合 Oracle、Salesforce、ServiceNow 官方资料整理。</em></p><h3 id="结构化能力数据说明" tabindex="-1">结构化能力数据说明 <a class="header-anchor" href="#结构化能力数据说明" aria-label="Permalink to &quot;结构化能力数据说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>可观察结构</th><th style="text-align:right;">Oracle</th><th style="text-align:right;">Salesforce</th><th style="text-align:right;">ServiceNow</th></tr></thead><tbody><tr><td>明确提到业务数据 / 对象</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr><tr><td>明确提到 Workflow / Flow</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr><tr><td>明确提到权限或安全继承</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr><tr><td>明确提到人工审批 / 升级</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr><tr><td>明确提到审计 / 观察</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr><tr><td>明确支持多 Agent / 专门角色</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr></tbody></table><p><code>1</code> 表示官方材料明确公开该结构，不表示实现深度相同，也不代表独立验证通过。该表用于说明三种平台在关键企业执行构件上的结构性趋同。</p><h2 id="new-architecture-judgment" tabindex="-1">New Architecture Judgment <a class="header-anchor" href="#new-architecture-judgment" aria-label="Permalink to &quot;New Architecture Judgment&quot;">​</a></h2><h3 id="_1-企业-agent-的长期壁垒在业务上下文-不只在模型" tabindex="-1">1. 企业 Agent 的长期壁垒在业务上下文，不只在模型 <a class="header-anchor" href="#_1-企业-agent-的长期壁垒在业务上下文-不只在模型" aria-label="Permalink to &quot;1. 企业 Agent 的长期壁垒在业务上下文，不只在模型&quot;">​</a></h3><p>企业执行依赖长期积累的业务对象、角色权限、政策、审批、交易历史和审计。如果 Agent 脱离这些上下文，就必须重新构建整套企业控制结构。</p><h3 id="_2-agentic-application-将比通用-agent-更接近可购买产品" tabindex="-1">2. Agentic Application 将比通用 Agent 更接近可购买产品 <a class="header-anchor" href="#_2-agentic-application-将比通用-agent-更接近可购买产品" aria-label="Permalink to &quot;2. Agentic Application 将比通用 Agent 更接近可购买产品&quot;">​</a></h3><p>组织购买的是“完成招聘、审批采购、处理服务请求、推进销售流程”，而不是“拥有更多 Agent”。Agentic Application 以结果、流程和责任为边界，更容易形成真实产品。</p><h3 id="_3-system-of-execution-必须保留确定性外壳" tabindex="-1">3. System of Execution 必须保留确定性外壳 <a class="header-anchor" href="#_3-system-of-execution-必须保留确定性外壳" aria-label="Permalink to &quot;3. System of Execution 必须保留确定性外壳&quot;">​</a></h3><p>AI 可以提出计划、选择工具和处理例外，但权限、状态迁移、审批、交易提交、证据和完成判断仍需要确定性控制。</p><h3 id="_4-原生集成与开放运行存在张力" tabindex="-1">4. 原生集成与开放运行存在张力 <a class="header-anchor" href="#_4-原生集成与开放运行存在张力" aria-label="Permalink to &quot;4. 原生集成与开放运行存在张力&quot;">​</a></h3><p>原生平台提供最强上下文、安全和审计，但容易形成厂商绑定。开放 Runtime 更灵活，却必须自行解决身份、业务对象、权限、恢复和审计。面向中小企业的系统需要在两者之间找到最小可行平衡。</p><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>本报告不直接修改 TMPA 出版物。它提供了一个重要研究输入：企业执行不只是 Message 或 Tool Call，而是围绕 Authority、Lifecycle、Reference、Event、Evidence 和 Governance Judgment 形成可重建工作记录。</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>数字员工应被包装为面向岗位和业务结果的 Agentic Work Application，而不是裸 Agent。最小组成包括：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Position</span></span>
<span class="line"><span>+ Work Catalog</span></span>
<span class="line"><span>+ Workflow</span></span>
<span class="line"><span>+ Runtime</span></span>
<span class="line"><span>+ Tool / Skill</span></span>
<span class="line"><span>+ Authority</span></span>
<span class="line"><span>+ Human Escalation</span></span>
<span class="line"><span>+ Evidence / Evaluation</span></span></code></pre></div><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu 的机会不是复制 Oracle、Salesforce 或 ServiceNow 的大型业务平台，而是提供独立、轻量、SME-first 的工作 Runtime，把外部业务系统、浏览器、Windows 操作和 API 统一纳入 WorkOrder、恢复、证据和完成门禁。</p><h2 id="next-week-research" tabindex="-1">Next Week Research <a class="header-anchor" href="#next-week-research" aria-label="Permalink to &quot;Next Week Research&quot;">​</a></h2><ol><li>研究 SAP Joule Agents 与 Microsoft Copilot Studio 的 Agentic Application 模式。</li><li>比较原生事务系统和外置 Runtime 的恢复能力。</li><li>定义 Agentic Application 的最小可移植契约。</li><li>研究业务完成与 Agent 自报完成之间的差异。</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Oracle, <strong>Oracle Introduces Fusion Agentic Applications</strong>: <a href="https://www.oracle.com/uk/news/announcement/oracle-introduces-fusion-agentic-applications-2026-03-24/" target="_blank" rel="noreferrer">https://www.oracle.com/uk/news/announcement/oracle-introduces-fusion-agentic-applications-2026-03-24/</a></li><li>Oracle, <strong>AI-Native Builder Experience for Fusion Agentic Applications</strong>: <a href="https://www.oracle.com/europe/news/announcement/oracle-introduces-ai-native-builder-experience-2026-07-14/" target="_blank" rel="noreferrer">https://www.oracle.com/europe/news/announcement/oracle-introduces-ai-native-builder-experience-2026-07-14/</a></li><li>Oracle Documentation, <strong>Overview of AI Agent Studio</strong>: <a href="https://docs.oracle.com/en/cloud/saas/fusion-ai/26c/aiaas/overview.html" target="_blank" rel="noreferrer">https://docs.oracle.com/en/cloud/saas/fusion-ai/26c/aiaas/overview.html</a></li><li>Oracle Documentation, <strong>Key Capabilities of AI Agent Studio</strong>: <a href="https://docs.oracle.com/en/cloud/saas/fusion-ai/26b/aiaas/key-capabilities.html" target="_blank" rel="noreferrer">https://docs.oracle.com/en/cloud/saas/fusion-ai/26b/aiaas/key-capabilities.html</a></li><li>Salesforce, <strong>Agentforce 360 Platform</strong>: <a href="https://www.salesforce.com/platform/agentforce-platform" target="_blank" rel="noreferrer">https://www.salesforce.com/platform/agentforce-platform</a></li><li>Salesforce, <strong>Introducing Agentforce 2.0</strong>: <a href="https://www.salesforce.com/news/press-releases/2024/12/17/agentforce-2-0-announcement/" target="_blank" rel="noreferrer">https://www.salesforce.com/news/press-releases/2024/12/17/agentforce-2-0-announcement/</a></li><li>ServiceNow, <strong>Autonomous Workforce</strong>: <a href="https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-launches-Autonomous-Workforce-that-thinks-and-acts-adds-Moveworks-to-the-ServiceNow-AI-Platform/default.aspx" target="_blank" rel="noreferrer">https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-launches-Autonomous-Workforce-that-thinks-and-acts-adds-Moveworks-to-the-ServiceNow-AI-Platform/default.aspx</a></li><li>ServiceNow, <strong>AI Control Tower</strong>: <a href="https://www.servicenow.com/products/ai-control-tower.html" target="_blank" rel="noreferrer">https://www.servicenow.com/products/ai-control-tower.html</a></li></ol>`,52))])}const A=a(l,[["render",c]]);export{m as __pageData,A as default};
